EPOCH = 1700000000000  # custom epoch (ms)

class Snowflake:
    def __init__(self, machine_id):
        self.machine_id = machine_id & 0x3FF   # 10 bits
        self.seq = 0
        self.last_ms = -1

    def next_id(self):
        ms = current_millis()
        if ms == self.last_ms:
            self.seq = (self.seq + 1) & 0xFFF   # 12 bits
            if self.seq == 0:                    # overflow → wait next ms
                ms = wait_next_millis(self.last_ms)
        else:
            self.seq = 0
        self.last_ms = ms
        return ((ms - EPOCH) << 22) | (self.machine_id << 12) | self.seq
